import React from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { format, isValid, parseISO } from "date-fns";
import { es, fr, enUS } from "date-fns/locale";
import images from "../images";
import SEO from "../components/seo";
import AppLink from "./AppLink";
import type { Company } from "../interfaces";
import { buildPersonSchema } from "../utils/structuredData";

type FaqItem = { q: string; a: string };

interface PostProps {
  date: string;
  updatedDate?: string;
  slug: string;
  data: Company;
}

const useBlogPostData = ({ date, updatedDate, slug, data }: PostProps) => {
  const { t, i18n } = useTranslation(["blog", "index"]);

  const getLocale = (language: string) => {
    switch (language) {
      case "es":
        return es;
      case "fr":
        return fr;
      default:
        return enUS;
    }
  };

  // FR default (sin prefijo), EN/ES con prefijo
  const langPrefix = i18n.language === "fr" ? "" : `/${i18n.language}`;
  const localizedPath = langPrefix
    ? `${langPrefix}/blog/${slug}/`
    : `/blog/${slug}/`;

  const urls = {
    aiSearch: `${langPrefix}/services/ai-search-optimization/`,
    seo: `${langPrefix}/services/seo/`,
    web: `${langPrefix}/services/web-design-development/`,
    portfolio: `${langPrefix}/portfolio/`,
    contact: `${langPrefix}/contact/`,
  };
  const geoClusterSlugs = new Set([
    "what_is_geo_ai_search_optimization",
    "seo_vs_geo_vs_aeo",
    "service_pages_citable_ai_search",
    "structured_data_for_ai_search",
    "proof_results_clear_claims_ai_search",
    "how_to_measure_geo_visibility",
  ]);

  const metaTitle =
    (t(`blog.${slug}-metaTitle`) as string) ||
    (t(`blog.${slug}-title`) as string) ||
    "";

  const h1Title = (t(`blog.${slug}-title`) as string) || "";
  const metaDescription = (t(`blog.${slug}-description`) as string) || "";
  const excerptHtml = (t(`blog.${slug}-excerpt`) as string) || "";

  const tldrRaw = t(`blog.${slug}-tldr`, { returnObjects: true }) as unknown;
  const faqsRaw = t(`blog.${slug}-faqs`, { returnObjects: true }) as unknown;

  const tldr = Array.isArray(tldrRaw) ? (tldrRaw as string[]) : [];
  const faqs = Array.isArray(faqsRaw) ? (faqsRaw as FaqItem[]) : [];

  const formatDate = (value: string) => {
    const parsed = parseISO(value);
    if (!isValid(parsed)) {
      return value;
    }

    return format(parsed, "MMMM dd, yyyy", {
      locale: getLocale(i18n.language),
    });
  };

  const formattedDate = formatDate(date);
  const formattedUpdatedDate = updatedDate ? formatDate(updatedDate) : formattedDate;

  const postImage =
    images[slug as keyof typeof images] ?? images.bg_workflow;

  // FAQ schema
  const faqSchema =
    faqs.length > 0
      ? {
          "@context": "https://schema.org",
          "@type": "FAQPage",
          mainEntity: faqs.map((item) => ({
            "@type": "Question",
            name: item.q,
            acceptedAnswer: { "@type": "Answer", text: item.a },
          })),
        }
      : null;

  // OG image absoluto (recomendado). Si postImage.src ya es absoluto, úsalo tal cual.
  const ogImage =
    postImage?.src && /^https?:\/\//i.test(postImage.src)
      ? postImage.src
      : postImage?.src
        ? `${data.url}${postImage.src.startsWith("/") ? postImage.src : `/${postImage.src}`}`
        : undefined;

  const siteUrl = (data?.url || "").replace(/\/+$/, "");
  const canonicalUrl = siteUrl ? `${siteUrl}${localizedPath}` : undefined;
  const personSchema = data.founder?.name
    ? buildPersonSchema({
        siteUrl,
        profilePath: i18n.language === "fr" ? "/about/" : `/${i18n.language}/about/`,
        name: data.founder.name,
        jobTitle: t("about.profile.role", { ns: "index" }) as string,
        description: t("about.profile.summary", { ns: "index" }) as string,
        inLanguage: i18n.language,
        sameAs: data.founder.sameAs,
        worksForName: data.companyName || "Code Crafted Studios",
      })
    : undefined;

  const personId = data.founder?.name && siteUrl ? `${siteUrl}/#person` : undefined;

  const articleSchema = canonicalUrl
    ? {
        "@context": "https://schema.org",
        "@type": "BlogPosting",
        headline: metaTitle || h1Title,
        description: metaDescription,
        datePublished: new Date(date).toISOString(),
        dateModified: new Date(updatedDate || date).toISOString(),
        inLanguage: i18n.language,
        url: canonicalUrl,
        mainEntityOfPage: canonicalUrl,
        ...(ogImage ? { image: ogImage } : {}),
        author: personId
          ? {
              "@id": personId,
            }
          : {
              "@type": "Organization",
              name: data.companyName || "Code Crafted Studios",
              url: siteUrl || undefined,
            },
        ...(personId
          ? {
              reviewedBy: {
                "@id": personId,
              },
            }
          : {}),
        publisher: {
          "@type": "Organization",
          name: data.companyName || "Code Crafted Studios",
          url: siteUrl || undefined,
        },
      }
    : null;

  // Labels simples por idioma (si quieres, luego los movemos a i18n keys)
  const labels =
    i18n.language === "fr"
      ? {
          tldr: "Points clés",
          faq: "FAQ",
          contact: "Nous contacter",
          web: "Web Design & Development",
          by: "Par",
          published: "Publié",
          updated: "Mis à jour",
          reviewedBy: "Révisé par",
          authorCta: "Voir le profil",
          aiSearch: "Optimisation recherche IA",
        }
      : i18n.language === "es"
        ? {
            tldr: "Puntos clave",
            faq: "Preguntas frecuentes",
            contact: "Contáctanos",
            web: "Diseño y Desarrollo Web",
            by: "Por",
            published: "Publicado",
            updated: "Actualizado",
            reviewedBy: "Revisado por",
            authorCta: "Ver perfil",
            aiSearch: "Optimización para búsqueda con IA",
          }
        : {
            tldr: "Key takeaways",
            faq: "FAQ",
            contact: "Contact us",
            web: "Web Design & Development",
            by: "By",
            published: "Published",
            updated: "Updated",
            reviewedBy: "Reviewed by",
            authorCta: "View profile",
            aiSearch: "AI Search Optimization",
          };
  const authorSummary = t("about.profile.summary", { ns: "index" }) as string;
  const authorRole = t("about.profile.role", { ns: "index" }) as string;
  const showAiSearchLink = geoClusterSlugs.has(slug);

  return {
    articleSchema,
    authorSummary,
    authorRole,
    excerptHtml,
    faqSchema,
    faqs,
    formattedDate,
    formattedUpdatedDate,
    h1Title,
    labels,
    localizedPath,
    metaDescription,
    metaTitle,
    ogImage,
    personSchema,
    postImage,
    showAiSearchLink,
    tldr,
    urls,
  };
};

export const BlogHead: React.FC<PostProps> = (props) => {
  const { metaTitle, metaDescription, ogImage, localizedPath, articleSchema, faqSchema, personSchema } =
    useBlogPostData(props);
  const additionalSchemas = [personSchema, articleSchema, faqSchema].filter(
    Boolean
  ) as object[];

  return (
    <SEO
      data={props.data}
      title={metaTitle}
      description={metaDescription}
      image={ogImage}
      pathname={localizedPath}
      schemaType="Organization"
      additionalSchemas={additionalSchemas.length ? additionalSchemas : undefined}
    />
  );
};

const Post: React.FC<PostProps> = (props) => {
  const { authorRole, authorSummary, excerptHtml, faqs, formattedDate, formattedUpdatedDate, h1Title, labels, postImage, showAiSearchLink, tldr, urls } =
    useBlogPostData(props);
  const authorName = props.data.founder?.name || props.data.companyName;
  const resolvedAuthorRole = props.data.founder?.name ? authorRole : "";
  const showUpdatedDate = !!props.updatedDate && props.updatedDate !== props.date;

  return (
    <article className="post-content flex flex-col items-center">
        <h1 className="text-3xl text-center">{h1Title}</h1>
        <div className="mt-3 grid w-full max-w-2xl grid-cols-1 gap-y-1 text-sm text-secondary md:grid-cols-2 md:gap-x-8 md:gap-y-2">
          <span className="text-center sm:text-left">
            {labels.by} {authorName}
            {resolvedAuthorRole ? `, ${resolvedAuthorRole}` : ""}
          </span>
          <span className="text-center sm:text-right">{labels.published} {formattedDate}</span>
          {showUpdatedDate ? <span className="text-center sm:text-left">{labels.updated} {formattedUpdatedDate}</span> : null}
          {props.data.founder?.name ? <span className={`${!showUpdatedDate ? 'text-center sm:text-left' : 'text-center sm:text-right'}`}>{labels.reviewedBy} {props.data.founder.name}</span> : null}
        </div>

        {postImage?.src ? (
          <img
            className="mx-auto my-4"
            src={postImage.src}
            alt={postImage.alt || h1Title}
          />
        ) : null}

        {/* TL;DR */}
        {tldr.length > 0 ? (
          <section className="w-full max-w-3xl my-6">
            <h2 className="text-xl font-semibold mb-2">{labels.tldr}</h2>
            <ul className="list-disc pl-6 space-y-1">
              {tldr.map((item, idx) => (
                <li key={idx}>{item}</li>
              ))}
            </ul>

            <div className="mt-4 flex flex-wrap gap-3">
              <AppLink className="underline" to={urls.seo}>
                SEO
              </AppLink>
              {showAiSearchLink ? (
                <AppLink className="underline" to={urls.aiSearch}>
                  {labels.aiSearch}
                </AppLink>
              ) : null}
              <AppLink className="underline" to={urls.web}>
                {labels.web}
              </AppLink>
              <AppLink className="underline" to={urls.portfolio}>
                Portfolio
              </AppLink>
              <AppLink className="underline" to={urls.contact}>
                {labels.contact}
              </AppLink>
            </div>
          </section>
        ) : null}

        {/* Main content */}
        <div dangerouslySetInnerHTML={{ __html: excerptHtml }} />

        <section className="w-full max-w-3xl my-8 rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light">
          <p className="text-xs font-semibold uppercase tracking-[0.14em] text-secondary">
            {labels.reviewedBy}
          </p>
          <h2 className="mt-2 text-xl font-semibold text-light/90">{authorName}</h2>
          {resolvedAuthorRole ? (
            <p className="mt-1 text-sm text-light/70">{resolvedAuthorRole}</p>
          ) : null}
          <p className="mt-3 text-sm sm:text-base text-light/80 leading-relaxed">
            {props.data.founder?.name ? authorSummary : props.data.companyName}
          </p>
          <div className="mt-4">
            <a
              className="underline text-sm"
              href="https://riano.ca"
              target="_blank"
              rel="noreferrer"
            >
              {labels.authorCta}
            </a>
          </div>
        </section>

        {/* FAQs */}
        {faqs.length > 0 ? (
          <section className="w-full max-w-3xl my-8">
            <h2 className="text-2xl font-semibold mb-4">{labels.faq}</h2>
            <div className="space-y-4">
              {faqs.map((item, idx) => (
                <div key={idx}>
                  <h3 className="font-semibold">{item.q}</h3>
                  <p className="mt-1">{item.a}</p>
                </div>
              ))}
            </div>

            <div className="mt-6">
              <AppLink className="underline" to={urls.contact}>
                {labels.contact}
              </AppLink>
            </div>
          </section>
        ) : null}
      </article>
  );
};

export default Post;
